function JacobianDeterminant2D(F0, F1):
    a <- pderiv(F0, x)      # dF0/dx
    d <- pderiv(F1, y)      # dF1/dy
    b <- pderiv(F0, y)      # dF0/dy
    c <- pderiv(F1, x)      # dF1/dx
    return polySub(polyMul(a, d), polyMul(b, c))

function pderiv(P, var):
    out <- empty polynomial
    for (monomial, coeff) in P:
        e <- exponent of var in monomial
        if e > 0:
            m' <- monomial with var-exponent decremented
            out[m'] <- out[m'] + coeff * e
    return out

